// prototype of syllableRules
export const SONORANTS = new Set(["ง","ญ","ณ","น","ม","ย","ร","ล","ว","ฬ"]);
export const TRUE_CLUSTERS = ["กร","ขร","คร","ตร","ปร","พร","กล","ขล","คล","ปล","ผล","พล","กว","ขว","คว"];
export const FALSE_CLUSTERS = {"ทร":"ซ","ซร":"ซ"};      // reads as /s/
export const SILENT_SECOND = ["จร","ศร","สร"];          // ร dropped
const CLUSTER = new Map();
for(const p of TRUE_CLUSTERS) CLUSTER.set(p,{kind:"true"});
for(const [p,s] of Object.entries(FALSE_CLUSTERS)) CLUSTER.set(p,{kind:"false-sound",soundOf:s});
for(const p of SILENT_SECOND) CLUSTER.set(p,{kind:"silent-second"});

const isCons=c=>c>="ก"&&c<="ฮ";
const CLASS = null; // filled later from symbols

// syllable shapes over a bare consonant run.
// returns list of {len, syl}
function shapesAt(chars, i, atWordStart){
  const out=[];
  const c=(k)=>chars[i+k];
  const rest=chars.length-i;
  const isVowelO=(k)=> c(k)==="อ" && !(atWordStart && k===0);
  const isVowelW=(k)=> c(k)==="ว" && k>0;
  // initial: 1 char, or 2 if a declared cluster
  for(const ilen of [1,2]){
    if(rest<ilen) continue;
    let initial, clusterKind=null;
    if(ilen===2){
      const pair=c(0)+c(1);
      const info=CLUSTER.get(pair);
      if(!info) continue;
      if(isVowelW(1)) continue;           // ว is the vowel here, not a cluster
      initial=pair; clusterKind=info.kind;
    } else {
      initial=c(0);
      if(atWordStart===false && initial==="อ") continue; // อ mid-word is a vowel
    }
    let j=ilen;
    // รร (ro han)
    if(c(j)==="ร"&&c(j+1)==="ร"){
      // รร + final, or รร alone
      if(j+2<rest && isCons(c(j+2))) out.push({len:ilen+3, initial, clusterKind, vowel:"รร", vowelSound:"a", final:c(j+2), rule:"ro-han"});
      if(j+2===rest) out.push({len:ilen+2, initial, clusterKind, vowel:"รร", vowelSound:"a", final:"น", rule:"ro-han"});
      continue;
    }
    // written vowel letter อ or ว
    if(isVowelO(j)||isVowelW(j)){
      const v=c(j), vowel=v==="อ"?"-อ":"-ัว";
      const vs=v==="อ"?"aaw":"ua";
      if(j+1<rest && isCons(c(j+1)) ) out.push({len:ilen+2, initial, clusterKind, vowel, vowelSound:vs, final:c(j+1), rule:v==="อ"?"o-as-vowel":"w-as-vowel"});
      out.push({len:ilen+1, initial, clusterKind, vowel, vowelSound:vs, final:null, rule:v==="อ"?"o-as-vowel":"w-as-vowel"});
      continue;
    }
    // bare ร as the whole remainder of the syllable -> /ɔːn/
    if(c(j)==="ร" && ilen===1){
      out.push({len:ilen+1, initial, clusterKind, vowel:"(อ)", vowelSound:"aaw", final:"ร", rule:"bare-final-ro"});
    }
    // implicit short o, with a final
    if(j<rest && isCons(c(j))) out.push({len:ilen+1, initial, clusterKind, vowel:"(โ-ะ)", vowelSound:"o", final:c(j), rule:"implicit-o"});
  }
  return out;
}

// leading-consonant prefix: ห + sonorant, consumes 1 char and marks the next syllable
export function segment(word){
  const chars=[...word];
  if(!chars.every(isCons)) return null;
  const results=[];
  const walk=(i, acc)=>{
    if(results.length>8) return;
    if(i===chars.length){ results.push(acc.slice()); return; }
    const atStart = i===0;
    // silent ห leading: ห + sonorant + (at least one more char)
    if(chars[i]==="ห" && SONORANTS.has(chars[i+1]) && chars.length-i>=3){
      for(const s of shapesAt(chars,i+1,false)){
        acc.push({...s, leader:"ห", leaderKind:"silent-h", len:s.len+1});
        walk(i+1+s.len, acc); acc.pop();
      }
    }
    for(const s of shapesAt(chars,i,atStart)){
      acc.push(s); walk(i+s.len, acc); acc.pop();
    }
    // unwritten -ะ leader syllable: one consonant standing alone, must be followed by more
    if(chars.length-i>=2 && !(!atStart && chars[i]==="อ")){
      acc.push({len:1, initial:chars[i], clusterKind:null, vowel:"(-ะ)", vowelSound:"a", final:null, rule:"implicit-a-leader", isLeader:true});
      walk(i+1, acc); acc.pop();
    }
  };
  walk(0,[]);
  return results;
}
