import { describe, expect, it } from "vitest";
import vocabularyData from "../../vocabulary/data/vocabulary.json";
import {
	type CorpusEntry,
	isBareConsonantWord,
	reconcileWithCorpus,
	resolveWord,
} from "./syllableRules";

const corpus = vocabularyData as unknown as (CorpusEntry & {
	romanization?: string;
})[];

const TONE_BY_DIACRITIC: Record<string, string> = {
	"̀": "low",
	"́": "high",
	"̂": "falling",
	"̌": "rising",
};

function tonesOf(romanization: string): string[] {
	return romanization
		.split(/[ -]+/)
		.filter(Boolean)
		.map((syllable) => {
			const marks = [...syllable.normalize("NFD")].filter(
				(c) => TONE_BY_DIACRITIC[c],
			);
			return marks.length ? TONE_BY_DIACRITIC[marks[0]] : "mid";
		});
}

describe("measure", () => {
	it("prints", () => {
		const bare = corpus.filter(
			(e) =>
				typeof e.rank === "number" &&
				(e.rank as number) <= 2000 &&
				isBareConsonantWord(e.thai),
		);
		let toneOk = 0;
		const toneBad: string[] = [];
		const unres: string[] = [];
		for (const e of bare) {
			const r = resolveWord(e.thai);
			if (r.state !== "resolved") {
				unres.push(`${e.thai}:${r.state}:${r.state === "unresolvable" ? r.ranOutAt : ""}`);
				continue;
			}
			const expected = tonesOf(e.romanization ?? "");
			const got = r.syllables.map((s) => s.tone);
			if (
				expected.length === got.length &&
				expected.every((t, i) => t === got[i])
			)
				toneOk++;
			else
				toneBad.push(
					`${e.rank} ${e.thai} ${e.romanization} exp=${expected.join(",")} got=${got.join(",")}`,
				);
		}
		console.log("TONE ok", toneOk, "bad", toneBad.length, "unres", unres);
		for (const b of toneBad) console.log("  ", b);
		const rep = reconcileWithCorpus(corpus);
		console.log(
			"UNRES WORDS",
			corpus
				.filter((e) => resolveWord(e.thai).state === "unresolvable")
				.map((e) => `${e.thai}@${e.rank}`),
		);
		console.log("disagreements", rep.disagreements.length);
		expect(true).toBe(true);
	});
});
